import{_ as t,c as s,o,ah as r}from"./chunks/framework.RCw5T9E9.js";const p=JSON.parse('{"title":"Logs settings","description":"","frontmatter":{"title":"Logs settings"},"headers":[],"relativePath":"logs/settings.md","filePath":"logs/settings.md"}'),n={name:"logs/settings.md"};function a(d,e,i,g,h,l){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="logs-settings" tabindex="-1">Logs settings <a class="header-anchor" href="#logs-settings" aria-label="Permalink to &quot;Logs settings&quot;">​</a></h1><p><strong>Options → Logs</strong> collects the settings of the <a href="./general.html">Logs</a> tab. The blocks follow in this order: <strong>Search Settings</strong>, <strong>Logs and limits</strong>, <strong>Ignore list</strong>, <strong>Data masking</strong>, <strong>Export</strong>. Changes apply immediately.</p><hr><h2 id="search-settings" tabindex="-1">Search Settings <a class="header-anchor" href="#search-settings" aria-label="Permalink to &quot;Search Settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Checkbox</th><th>Default</th></tr></thead><tbody><tr><td><strong>Search by event name (title, component, store, URL)</strong></td><td>on</td></tr><tr><td><strong>Search by key (payload keys and changed paths)</strong></td><td>off</td></tr><tr><td><strong>Search by value (payload values)</strong></td><td>off</td></tr></tbody></table><p>How a query matches is in <a href="./general.html#search">Working with logs</a>. If key and value are both off, name search stays on.</p><hr><h2 id="logs-and-limits" tabindex="-1">Logs and limits <a class="header-anchor" href="#logs-and-limits" aria-label="Permalink to &quot;Logs and limits&quot;">​</a></h2><h3 id="logged-events" tabindex="-1">Logged events <a class="header-anchor" href="#logged-events" aria-label="Permalink to &quot;Logged events&quot;">​</a></h3><p>Each group has a checkbox: an unchecked group is not logged at all, and already logged events stay. All groups are on by default.</p><table tabindex="0"><thead><tr><th>Group</th><th>Events</th></tr></thead><tbody><tr><td><strong>Requests</strong></td><td><strong>Send request</strong> and <strong>Receive response</strong></td></tr><tr><td><strong>WebSocket</strong></td><td><strong>WebSocket open</strong>, <strong>WebSocket sent</strong>, <strong>WebSocket received</strong> and <strong>WebSocket closed</strong></td></tr><tr><td><strong>Props changes</strong></td><td><strong>Change props</strong></td></tr><tr><td><strong>Emits</strong></td><td><strong>Emit</strong></td></tr><tr><td><strong>Pinia changes</strong></td><td><strong>Change store</strong> (when checked again, the store starts with a new <strong>Store snapshot</strong>)</td></tr><tr><td><strong>Store actions</strong></td><td><strong>Store action</strong></td></tr><tr><td><strong>Navigation</strong></td><td><strong>Navigation</strong></td></tr><tr><td><strong>Clicks</strong></td><td><strong>Click</strong></td></tr><tr><td><strong>JS errors</strong></td><td><strong>JS error</strong></td></tr></tbody></table><p>The number beside each checkbox is how many events of that group are stored now. Its tooltip is <strong>Currently stored</strong>. <strong>Requests</strong> does not count <strong>Receive response</strong>, and the unit is <strong>requests</strong>. The other groups use <strong>events</strong>.</p><h3 id="data-size" tabindex="-1">Data size <a class="header-anchor" href="#data-size" aria-label="Permalink to &quot;Data size&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Range</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Memory budget</strong></td><td>20 MB</td><td>8 – 1024 MB</td><td>Total size of all buffered events (approximate serialized size). A network entry shared by a request and its response, and equal bodies, are counted once. A binary response counts as its format and size, not the file</td></tr><tr><td><strong>Limit event size</strong></td><td>on</td><td>—</td><td>On by default. Off: events are kept whole. The <strong>Max event size</strong> field is shown only while this is on</td></tr><tr><td><strong>Max event size</strong></td><td>512 KB</td><td>16 – 16 384 KB</td><td>Larger parts of an event (store snapshots, arguments, results) are dropped, network bodies are cut to this size</td></tr></tbody></table><p>When the memory budget is reached, the log is cut at a <strong>Navigation</strong> and every event before it is removed. <strong>Pinia</strong> changes up to that cut are rebuilt into a <strong>Store checkpoint</strong>, so the remaining changes keep their <strong>Before</strong> / <strong>After</strong>; the previous base and the diffs it was built from are removed (see <a href="./general.html#how-events-are-stored">How events are stored</a>). The last navigation is rewritten as a page snapshot, and if the log is still over the budget the oldest remaining events are removed. The newest event is always kept, even if it alone exceeds the budget. <strong>Send request</strong> and <strong>Receive response</strong> are also capped at <strong>Maximum HTTP requests</strong>, the same ring as HTTP rows on the Network tab (<strong>Options → Network</strong>, default <strong>500</strong>): the request and its response leave together. WebSocket log events are capped at <strong>Maximum WebSocket events</strong> (default <strong>500</strong>): open, sent, received and closed each count as one.</p><p>The line under the bar is <strong>Used {size} of {size} (approximate serialized size).</strong> The bar turns orange at 90 % and above.</p><p>A number outside the range is rounded and clamped to the nearest bound. A value that is not a number resets to the default. An empty field is treated as 0 and therefore becomes the minimum (8 MB or 16 KB). The new value is applied when the field is committed.</p><p><strong>Defaults</strong> on this block restores the group checkboxes, the budget, <strong>Limit event size</strong> and <strong>Max event size</strong>. It does not reset search, the ignore list, masking or <strong>Compress report</strong>.</p><hr><h2 id="ignore-list" tabindex="-1">Ignore list <a class="header-anchor" href="#ignore-list" aria-label="Permalink to &quot;Ignore list&quot;">​</a></h2><p>Event groups excluded from logging. A group is one subject: the same request (method and path), the same component, the same store, and so on. Ignored groups are not recorded at all.</p><p>Under the title: <strong>These event groups are not recorded. Log again resumes one group.</strong></p><table tabindex="0"><thead><tr><th>Column</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Type</strong></td><td>The event label (<strong>Send request</strong>, <strong>Change store</strong>, <strong>JS error</strong>, and the rest)</td></tr><tr><td><strong>Object</strong></td><td>The stored group key: URL, component, store, message, and so on</td></tr></tbody></table><p>The row menu is only <strong>Log again</strong>. <strong>Log all again</strong>, next to the title, clears the list and is disabled when it is empty. The empty table says <em>No ignored objects</em>. Clicking a row does nothing. There is no details card.</p><p>The <strong>ignored</strong> indicator on the <a href="./general.html">Logs</a> toolbar opens this table. It is hidden when the list is empty.</p><hr><h2 id="data-masking" tabindex="-1">Data masking <a class="header-anchor" href="#data-masking" aria-label="Permalink to &quot;Data masking {#data-masking}&quot;">​</a></h2><p>Values are masked <strong>when an event is captured</strong>, so they never reach the <strong>Logs</strong> view or exports.</p><p>Under the title: <strong>Values are masked when an event is captured, so they never reach the Logs view or exports.</strong></p><p>Both checkboxes are labeled <strong>Mask sensitive data</strong>.</p><ul><li>The first turns masking on. It is on by default. While it is off, the key list is dimmed and captured values are stored as they are.</li><li>The second is directly under it and is disabled while the first is off. It is on by default. It masks <strong>JWT</strong> (<code>[MASKED JWT]</code>), <strong>Bearer</strong> / <strong>Basic</strong> / <strong>Token</strong> credentials (<code>Bearer [MASKED]</code>) and card numbers (<code>[MASKED CARD]</code>) inside any text of 8 characters or more. There is no separate label for that behavior.</li></ul><p>The key list header is <strong>Key contains</strong>. The empty table says <em>No keys — only value patterns are masked</em>. The add field placeholder is <strong>Key fragment, e.g. accessCode</strong>. <strong>Add</strong> or <strong>Enter</strong> trims the fragment. An empty value shows <strong>Key cannot be empty</strong>. The same fragment, ignoring case, shows <strong>This key is already in the list</strong>. The row menu is <strong>Delete</strong>. Clicking a row does nothing.</p><p>Default keys: <code>password</code>, <code>passwd</code>, <code>pwd</code>, <code>secret</code>, <code>token</code>, <code>authorization</code>, <code>cookie</code>, <code>apikey</code>, <code>sessionid</code>, <code>privatekey</code>, <code>creditcard</code>, <code>cardnumber</code>, <code>cvv</code>, <code>cvc</code>, <code>ssn</code>, <code>otp</code>.</p><p>Keys match case-insensitively and ignore separators (<code>api_key</code>, <code>api-key</code> and <code>apiKey</code> are the same). Fragments of <strong>4 letters or fewer</strong> must match a whole word, so <code>pwd</code> or <code>otp</code> do not mask unrelated keys.</p><p><strong>Defaults</strong>, next to the title, restores both checkboxes and the key list.</p><p>Masked values of sensitive keys are replaced with <code>[MASKED]</code>. Card numbers are checked with the Luhn algorithm.</p><hr><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export {#export}&quot;">​</a></h2><p><strong>Compress report</strong> is on by default. While the browser can compress, the helper says <strong>The HTML report is several times smaller. Needs Chrome / Edge 80+, Firefox 113+ or Safari 16.4+.</strong> The file then stores the event JSON as gzip in base64. In a browser that cannot compress, the checkbox is disabled and the helper says <strong>Not supported in this browser. Needs Chrome / Edge 80+, Firefox 113+ or Safari 16.4+.</strong> What the file contains is in <a href="./export.html">Export</a>.</p><hr><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./general.html">Working with logs</a></li><li><a href="./export.html">Export</a></li><li><a href="/qa-tools/docs/options/settings_management.html">Settings management</a></li></ul>',42)])])}const m=t(n,[["render",a]]);export{p as __pageData,m as default};
